//! `MineHouse` vanilla-parity suite.
//!
//! Runs every `minehouse:*` test instance from
//! `assets/tests/datapacks/minehouse-parity` (generated by
//! `tools/minehouse-parity/gen_tests.py`). The same datapack runs on the vanilla
//! 26.3 server, so a test that passes there and fails here is a Pumpkin gap.
//!
//! Unlike the main suite, every test gets its own batch report, so a failing
//! test doesn't hide the others and the result can be written per test.

use std::sync::{Arc, Mutex as StdMutex};

use pumpkin_core::server::{
    Server,
    server_test_manager::{
        GameTestBatchReport, GameTestQueueEntry, GameTestRetryOptions,
        prepare_test_run_with_reporter,
    },
};
use pumpkin_data::{dimension::Dimension, test_instance::all_test_instance_names};
use pumpkin_gametest::{GameTestReporter, GameTestRunner};
use pumpkin_util::{math::vector2::Vector2, text::TextComponent};

use crate::gametests::force_load_surroundings_chunks;

const NAMESPACE: &str = "minehouse:";
const GRID_SPACING: i32 = 24;
const TESTS_PER_ROW: i32 = 4;
const BASE_X: i32 = 65;
const BASE_Y: i32 = 80;
const BASE_Z: i32 = 66;
/// Longest test (furnace) needs ~200 ticks; leave headroom for `max_ticks`.
const MAX_TICKS: usize = 600;

#[derive(Default)]
struct CaptureReporter {
    messages: StdMutex<Vec<String>>,
}

impl GameTestReporter for CaptureReporter {
    fn send_message(&self, message: TextComponent) {
        self.messages
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push(message.get_text());
    }
}

pub struct ParityResult {
    pub test_id: &'static str,
    pub passed: bool,
    pub messages: Vec<String>,
}

pub async fn run_parity(server: &Arc<Server>) -> Result<Vec<ParityResult>, String> {
    let world = server.get_world_from_dimension(&Dimension::OVERWORLD);
    let tests: Vec<&'static str> = all_test_instance_names()
        .iter()
        .copied()
        .filter(|id| id.starts_with(NAMESPACE))
        .collect();
    if tests.is_empty() {
        return Err("no minehouse:* test instances are compiled in".to_string());
    }

    let rows = (tests.len() as i32 + TESTS_PER_ROW - 1) / TESTS_PER_ROW;
    let min_cx = BASE_X >> 4;
    let min_cz = BASE_Z >> 4;
    let max_cx = (BASE_X + TESTS_PER_ROW * GRID_SPACING) >> 4;
    let max_cz = (BASE_Z + rows * GRID_SPACING) >> 4;
    force_load_surroundings_chunks(&world, min_cx, max_cx, min_cz, max_cz);
    for cx in min_cx..=max_cx {
        for cz in min_cz..=max_cz {
            world
                .level
                .get_or_fetch_chunk(Vector2::new(cx, cz), |_| ())
                .await;
        }
    }

    let mut runner = GameTestRunner::new();
    let mut runs = Vec::with_capacity(tests.len());
    for (slot, &test_id) in tests.iter().enumerate() {
        let slot = slot as i32;
        let reporter = Arc::new(CaptureReporter::default());
        let sink: Arc<dyn GameTestReporter> = reporter.clone();
        let report = Arc::new(GameTestBatchReport::new(sink.clone(), 1));
        let entry = GameTestQueueEntry::new(
            test_id,
            world.clone(),
            BASE_X + (slot % TESTS_PER_ROW) * GRID_SPACING,
            BASE_Z + (slot / TESTS_PER_ROW) * GRID_SPACING,
            0,
            GameTestRetryOptions::no_retries(),
            report.clone(),
        )
        .with_y(BASE_Y);
        match prepare_test_run_with_reporter(server, entry, sink).await {
            Ok(manager) => runner.enqueue(manager),
            Err(err) => reporter
                .messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(format!("failed to prepare: {err}")),
        }
        runs.push((test_id, reporter, report));
    }

    for _ in 0..MAX_TICKS {
        if runner.is_empty() {
            break;
        }
        server.tick();
        runner.tick().await;
    }
    runner.clear();

    Ok(runs
        .into_iter()
        .map(|(test_id, reporter, report)| {
            let mut messages = reporter
                .messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone();
            let passed = report.is_done() && report.all_required_passed();
            if !report.is_done() {
                messages.push(format!("did not finish within {MAX_TICKS} ticks"));
            }
            ParityResult {
                test_id,
                passed,
                messages,
            }
        })
        .collect())
}
